// MONOTERMINAL Text Rendering Shader
// Target: 60 FPS (16.67ms frame budget)
// GPU Budget: 8ms render time (per SRS §2.1.1)
//
// Renders glyphs from a 4096×4096 R8Unorm texture atlas
// Each glyph: position (screen space), tex_coord (atlas UV), color (RGBA)

// Vertex input structure
struct VertexInput {
    @location(0) position: vec2<f32>,    // Screen-space position (NDC: -1 to +1)
    @location(1) tex_coord: vec2<f32>,   // Atlas UV coordinates (0.0 to 1.0)
    @location(2) color: vec4<f32>,       // Foreground color (RGBA, 0.0 to 1.0)
}

// Vertex output / Fragment input
struct VertexOutput {
    @builtin(position) clip_position: vec4<f32>,  // Required by wgpu (clip space)
    @location(0) tex_coord: vec2<f32>,            // Pass-through to fragment shader
    @location(1) color: vec4<f32>,                // Pass-through to fragment shader
}

// Texture atlas (R8Unorm = grayscale, stored in red channel)
@group(0) @binding(0)
var glyph_atlas: texture_2d<f32>;

// Atlas sampler (nearest filter for crisp text at exact pixel alignment)
@group(0) @binding(1)
var atlas_sampler: sampler;

// Vertex shader: transform to clip space, pass through tex_coord and color
@vertex
fn vs_main(vertex: VertexInput) -> VertexOutput {
    var out: VertexOutput;

    // Convert screen-space position to clip space (add Z=0, W=1 for 2D)
    out.clip_position = vec4<f32>(vertex.position, 0.0, 1.0);

    // Pass through texture coordinates and color unchanged
    out.tex_coord = vertex.tex_coord;
    out.color = vertex.color;

    return out;
}

// Fragment shader: sample atlas alpha, multiply with vertex color
@fragment
fn fs_main(in: VertexOutput) -> @location(0) vec4<f32> {
    // Sample glyph atlas (R8 format → alpha channel)
    // The atlas stores grayscale glyph shapes: 0.0 = transparent, 1.0 = opaque
    let glyph_alpha = textureSample(glyph_atlas, atlas_sampler, in.tex_coord).r;

    // Multiply vertex color with glyph alpha for text rendering
    // This allows colored text: color.rgb stays, color.a modulates with glyph shape
    return vec4<f32>(in.color.rgb, in.color.a * glyph_alpha);
}

